  3446  int sam_set_thread_pool(htsFile *fp, htsThreadPool *p) {
  3447      if (fp->state)
  3448          return 0;
  3449
  3450      if (!(fp->state = sam_state_create(fp)))
  3451          return -1;
  3452      SAM_state *fd = (SAM_state *)fp->state;
  3453
  3454      pthread_mutex_init(&fd->lines_m, NULL);
  3455      pthread_mutex_init(&fd->command_m, NULL);
  3456      pthread_cond_init(&fd->command_c, NULL);
  3457      fd->p = p->pool;
  3458      int qsize = p->qsize;
  3459      if (!qsize)
  3460          qsize = 2*hts_tpool_size(fd->p);
  3461      fd->q = hts_tpool_process_init(fd->p, qsize, 0);
  3462      if (!fd->q) {
  3463          sam_state_destroy(fp);
  3464          return -1;
  3465      }
  3466
  3467      if (fp->format.compression == bgzf)
  3468          return bgzf_thread_pool(fp->fp.bgzf, p->pool, p->qsize);
  3469
  3470      return 0;
  3471  }
